Running command: cd /tmp && cat > /tmp/driver4.cc <<'EOF'
#include <libexif/exif-data.h>
#include <libexif/exif-loader.h>
#include <stddef.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
int main(int argc, char** argv) {
  if (argc < 2) return 1;
  FILE* f = fopen(argv[1], "rb");
  if (!f) return 1;
  fseek(f, 0, SEEK_END);
  long sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  uint8_t* buf = (uint8_t*)malloc(sz);
  fread(buf, 1, sz, f);
  fclose(f);
  auto image = exif_data_new_from_data(buf, sz);
  if (image) {
    for (int ifd=0; ifd<EXIF_IFD_COUNT; ifd++) {
      printf("ifd %d count=%d\n", ifd, exif_content_get_count(image->ifd[ifd]));
    }
    exif_data_unref(image);
  } else printf("image null\n");
  free(buf);
  return 0;
}
EOF
